export type LanguageCode = string;

export interface LanguageInfo {
  code: LanguageCode;
  label: string;
  nativeLabel: string;
}

export type ImageryTreatment = 'grayscale' | 'duotone' | 'full-color';

export interface StyleSettings {
  backgroundColor: string;
  typographyColor: string;
  accentColor: string;
  uiColor: string;
  imageryTreatment: ImageryTreatment;
}

export interface StyleInfo {
  id: string;
  name: string;
  definition: string;
}

export interface GeneratedVideo {
  mediaId: string;
  base64: string;
  mimeType: string;
  duration: number;
}

export interface ReferenceAsset {
  id: string;
  name: string;
  originalBase64: string;
  processedBase64: string;
  mediaId?: string;
  status: 'idle' | 'processing' | 'ready' | 'error';
}

export interface TranslationStrings {
  languageSelectTitle: string;
  languageSelectSub: string;
  languageSelectAction: string;
  welcomeTitle: string;
  welcomeDesc: string;
  onboardingTitle: string;
  onboardingStep1: string;
  onboardingStep2: string;
  onboardingStep3: string;
  headerTitle: string;
  headerSub: string;
  step1Title: string;
  step1Sub: string;
  styleLabel: string;
  inputLabel: string;
  sceneLabel: string;
  scriptLabel: string;
  scriptAutoLabel: string;
  inputPlaceholder: string;
  scenePlaceholder: string;
  scriptPlaceholder: string;
  durationLabel: string;
  resLabel: string;
  aspectLabel: string;
  landscapeLabel: string;
  portraitLabel: string;
  draftLabel: string;
  hdLabel: string;
  audioTitle: string;
  voiceLabel: string;
  musicLabel: string;
  voiceFemale: string;
  voiceMale: string;
  voiceNone: string;
  musicOn: string;
  musicOff: string;
  textToggleLabel: string;
  textOn: string;
  textOff: string;
  genBtn: string;
  genLoading: string;
  errorInput: string;
  errorGen: string;
  step2Title: string;
  step2Sub: string;
  step2Desc: string;
  downloadVideo: string;
  shareTitle: string;
  readyToDownload: string;
  styleConsoleTitle: string;
  bgColorLabel: string;
  textColorLabel: string;
  accentColorLabel: string;
  uiColorLabel: string;
  imageryLabel: string;
  refToggleLabel: string;
  refManagerTitle: string;
  refNamePlaceholder: string;
  refUploadHint: string;
  refProcessing: string;
  // Tooltips
  tooltipImagery: string;
  tooltipBg: string;
  tooltipText: string;
  tooltipAccent: string;
  tooltipUI: string;
}

import React, { useState, useEffect, useRef } from 'react';
import { Step1VideoGen } from './components/Step1VideoGen';
import { Step2Preview } from './components/Step2Preview';
import { LanguageGate } from './components/LanguageGate';
import { StyleConsole } from './components/StyleConsole';
import { GeneratedVideo, LanguageCode, StyleSettings } from './types';
import { TRANSLATIONS } from './translations';
import { SUPPORTED_LANGUAGES } from './constants/Languages';

// Helper to determine if a color is light or dark
const getContrastColor = (hex: string) => {
  const r = parseInt(hex.slice(1, 3), 16);
  const g = parseInt(hex.slice(3, 5), 16);
  const b = parseInt(hex.slice(5, 7), 16);
  const luminance = (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  return luminance > 0.6 ? '#000000' : '#FFFFFF';
};

const ProcessingToast: React.FC<{ show: boolean; accentColor: string }> = ({ show, accentColor }) => (
  <div className={`fixed top-48 left-1/2 -translate-x-1/2 z-[500] transition-all duration-700 ease-[var(--expo-ease)] ${show ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-8 pointer-events-none'}`}>
    <div className="bg-white text-black border-2 border-black px-10 py-5 flex items-center gap-8 shadow-[0_30px_70px_rgba(0,0,0,0.7)] relative overflow-hidden">
      <div className="absolute top-0 left-0 w-2 h-full" style={{ backgroundColor: accentColor }} />
      <div className="w-8 h-8 border-[3px] border-black border-t-transparent rounded-full animate-spin shrink-0" />
      <div className="flex flex-col">
        <span className="mono-label text-black font-black text-[10px] tracking-[0.3em] mb-1 uppercase">proc.notice // core_render_active</span>
        <span className="text-[14px] font-black italic tracking-tight lowercase">rendering unit: this may take 1-2 minutes</span>
      </div>
    </div>
  </div>
);

const ErrorToast: React.FC<{ show: boolean; accentColor: string; message: string; onDismiss: () => void }> = ({ show, accentColor, message, onDismiss }) => (
  <div className={`fixed top-48 left-1/2 -translate-x-1/2 z-[510] transition-all duration-500 ease-[var(--expo-ease)] ${show ? 'opacity-100 translate-y-0' : 'opacity-0 -translate-y-8 pointer-events-none'}`}>
    <button 
      onClick={onDismiss}
      className="bg-black text-white border-2 border-white px-10 py-5 flex items-center gap-8 shadow-[0_30px_70px_rgba(0,0,0,0.9)] relative overflow-hidden text-left"
    >
      <div className="absolute top-0 left-0 w-2 h-full" style={{ backgroundColor: accentColor }} />
      <span className="material-symbols-outlined text-red-600 text-3xl">warning</span>
      <div className="flex flex-col">
        <span className="mono-label text-white/40 font-black text-[9px] tracking-[0.3em] mb-1 uppercase">system.alert // critical_validation</span>
        <span className="text-[14px] font-black italic tracking-tight uppercase">{message}</span>
      </div>
    </button>
  </div>
);

export default function App() {
  const [langCode, setLangCode] = useState<LanguageCode | null>(null);
  const [activeVideo, setActiveVideo] = useState<GeneratedVideo | null>(null);
  const scrollContainerRef = useRef<HTMLElement>(null);

  // Global Toast State
  const [isProcessing, setIsProcessing] = useState(false);
  const [errorMessage, setErrorMessage] = useState<string | null>(null);

  const [resolution, setResolution] = useState<'360p' | '720p'>('720p');
  const [aspectRatio, setAspectRatio] = useState<'16:9' | '9:16'>('16:9');

  const [styleSettings, setStyleSettings] = useState<StyleSettings>({
    backgroundColor: '#000000',
    typographyColor: '#FFFFFF',
    accentColor: '#FF0000',
    uiColor: '#FFFFFF',
    imageryTreatment: 'grayscale'
  });

  const t = langCode && TRANSLATIONS[langCode] ? TRANSLATIONS[langCode] : TRANSLATIONS['en'];
  const contrastColor = getContrastColor(styleSettings.backgroundColor);

  // Auto-dismiss error
  useEffect(() => {
    if (errorMessage) {
      const timer = setTimeout(() => setErrorMessage(null), 5000);
      return () => clearTimeout(timer);
    }
  }, [errorMessage]);

  // Autoscroll to video section when generated
  useEffect(() => {
    if (activeVideo && scrollContainerRef.current) {
      setTimeout(() => {
        const previewElement = document.getElementById('preview-section');
        if (previewElement) {
          previewElement.scrollIntoView({ behavior: 'smooth', block: 'start' });
        }
      }, 100);
    }
  }, [activeVideo]);

  useEffect(() => {
    const id = 'collage-modernist-css';
    let style = document.getElementById(id) as HTMLStyleElement;
    if (!style) {
      style = document.createElement('style');
      style.id = id;
      document.head.appendChild(style);
    }

    style.textContent = `
      :root {
        --canvas-bg: ${styleSettings.backgroundColor};
        --text-color: ${styleSettings.typographyColor};
        --accent-red: ${styleSettings.accentColor};
        --ui-color: ${styleSettings.uiColor};
        --ui-contrast: ${contrastColor};
        --ui-contrast-alpha: ${contrastColor === '#FFFFFF' ? 'rgba(255,255,255,0.03)' : 'rgba(0,0,0,0.05)'};
        --ui-contrast-muted: ${contrastColor === '#FFFFFF' ? 'rgba(255,255,255,0.4)' : 'rgba(0,0,0,0.4)'};
        --expo-ease: cubic-bezier(0.87, 0, 0.13, 1);
      }

      html, body, #root { 
        background: var(--canvas-bg); 
        color: var(--ui-contrast); 
        height: 100%; 
        margin: 0; 
        padding: 0; 
        font-family: 'Google Sans Text', 'Inter', sans-serif; 
        overflow: hidden;
        -webkit-font-smoothing: antialiased;
        transition: background 0.5s var(--expo-ease);
      }

      .swiss-grid {
        background-image: 
          linear-gradient(to right, var(--ui-contrast-alpha) 1px, transparent 1px),
          linear-gradient(to bottom, var(--ui-contrast-alpha) 1px, transparent 1px);
        background-size: 80px 80px;
      }

      .hud-marker {
        position: absolute;
        font-family: 'Roboto Mono', monospace;
        font-size: 10px;
        color: var(--ui-contrast-muted);
        pointer-events: none;
        text-transform: uppercase;
        transition: color 0.5s var(--expo-ease);
      }

      .mono-label { 
        font-family: 'Roboto Mono', monospace; 
        font-size: 10px; 
        letter-spacing: 0.25em; 
        text-transform: uppercase;
      }

      .kinetic-title {
        font-size: clamp(2.5rem, 6vw, 5rem);
        font-weight: 900;
        letter-spacing: -0.06em;
        line-height: 0.8;
        font-style: italic;
        text-transform: lowercase;
        color: var(--ui-contrast);
      }

      .dark-scrollbar::-webkit-scrollbar { width: 4px; }
      .dark-scrollbar::-webkit-scrollbar-track { background: transparent; }
      .dark-scrollbar::-webkit-scrollbar-thumb { background: var(--ui-contrast-muted); }

      @keyframes slide-drift {
        from { transform: translateX(-30px); opacity: 0; }
        to { transform: translateX(0); opacity: 1; }
      }
      .animate-drift { animation: slide-drift 1.5s var(--expo-ease) forwards; }

      @keyframes scale-in {
        from { transform: scale(0.95); opacity: 0; }
        to { transform: scale(1); opacity: 1; }
      }
      .animate-content { animation: scale-in 1.2s var(--expo-ease) forwards; }

      input[type=range] { -webkit-appearance: none; background: transparent; }
      input[type=range]::-webkit-slider-runnable-track { height: 1px; background: var(--ui-contrast-muted); }
      input[type=range]::-webkit-slider-thumb { -webkit-appearance: none; height: 12px; width: 12px; background: var(--accent-red); margin-top: -5.5px; border-radius: 50%; }

      @keyframes dropdown-enter { from { opacity: 0; transform: scale(0.95) translateY(-5px); } to { opacity: 1; transform: scale(1) translateY(0); } }
      .animate-dropdown { animation: dropdown-enter 0.3s var(--expo-ease) forwards; }
    `;
  }, [styleSettings, contrastColor]);

  if (!langCode) {
    return <LanguageGate onSelect={setLangCode} />;
  }

  const currentLangLabel = SUPPORTED_LANGUAGES.find(l => l.code === langCode)?.nativeLabel;

  return (
    <div className="flex h-screen w-screen overflow-hidden swiss-grid relative transition-colors duration-500" style={{ backgroundColor: styleSettings.backgroundColor }}>

      {/* Global Viewport Toasts (Outside transformed main container) */}
      <ProcessingToast show={isProcessing} accentColor={styleSettings.accentColor} />
      <ErrorToast 
        show={!!errorMessage} 
        accentColor={styleSettings.accentColor} 
        message={errorMessage || ''} 
        onDismiss={() => setErrorMessage(null)} 
      />

      {/* HUD Overlays (Global) */}
      <div className="hud-marker top-8 left-8">VHS 073</div>
      <div className="hud-marker top-8 right-8 flex items-center gap-2">
        <div className="w-2 h-2 rounded-full bg-red-600 animate-pulse" /> REC
      </div>
      <div className="hud-marker bottom-8 left-8">LUMA_BUFF // 0x2A</div>
      <div className="hud-marker bottom-8 right-8 flex flex-col items-end">
        <span>BATT 98%</span>
        <span>48kHz / 24bit</span>
      </div>

      {/* Main Studio Area */}
      <div className="flex-1 flex flex-col min-w-0 relative z-10">

        {/* Top Masthead */}
        <header className="h-44 flex items-stretch border-b shrink-0 transition-colors" style={{ borderColor: contrastColor, backgroundColor: contrastColor === '#FFFFFF' ? 'rgba(0,0,0,0.4)' : 'rgba(255,255,255,0.05)' }}>
          <div className="flex-1 p-12 flex flex-col justify-end gap-3 border-r animate-drift transition-colors" style={{ borderColor: contrastColor }}>
            <div className="flex items-center gap-4">
               <div className="w-2 h-2 rotate-45" style={{ backgroundColor: styleSettings.accentColor }} />
               <span className="mono-label font-bold uppercase tracking-widest" style={{ color: contrastColor }}>{t.headerTitle} // engine_v1.5</span>
            </div>
            <h1 className="kinetic-title" style={{ color: contrastColor }}>SwissFlow</h1>
          </div>

          <div className="w-80 p-12 flex flex-col justify-between items-end bg-white/[0.02]">
            <div className="flex flex-col items-end gap-2">
              <span className="mono-label opacity-40 uppercase" style={{ color: contrastColor }}>sys.locale</span>
              <div className="flex items-center gap-5">
                <span className="text-2xl font-black lowercase tracking-tighter italic" style={{ color: contrastColor }}>{currentLangLabel}</span>
                <button 
                  onClick={() => setLangCode(null)}
                  className="w-10 h-10 flex items-center justify-center border transition-all rounded-xl"
                  style={{ borderColor: contrastColor }}
                >
                  <span className="material-symbols-outlined text-[18px]" style={{ color: contrastColor }}>language</span>
                </button>
              </div>
            </div>
            <p className="text-[11px] lowercase font-medium tracking-widest text-right max-w-[160px] leading-tight" style={{ color: contrastColor, opacity: 0.7 }}>
              {t.headerSub}
            </p>
          </div>
        </header>

        {/* Dynamic Workflow View */}
        <main 
          ref={scrollContainerRef}
          className="flex-1 overflow-y-auto dark-scrollbar flex flex-col animate-content scroll-smooth"
        >

          <StyleConsole settings={styleSettings} onChange={setStyleSettings} t={t} contrastColor={contrastColor} />

          <Step1VideoGen 
            onVideoGen={setActiveVideo} 
            langCode={langCode}
            t={t}
            resolution={resolution}
            setResolution={setResolution}
            aspectRatio={aspectRatio}
            setAspectRatio={setAspectRatio}
            styleSettings={styleSettings}
            contrastColor={contrastColor}
            setGlobalLoading={setIsProcessing}
            setGlobalError={setErrorMessage}
          />

          {activeVideo && (
            <Step2Preview 
              video={activeVideo}
              t={t}
              resolution={resolution}
              aspectRatio={aspectRatio}
              styleSettings={styleSettings}
              contrastColor={contrastColor}
            />
          )}

          {/* Utility Footer */}
          <footer className="p-12 flex justify-between items-center mt-auto border-t transition-colors" style={{ borderColor: contrastColor, backgroundColor: contrastColor === '#FFFFFF' ? 'rgba(0,0,0,0.4)' : 'rgba(255,255,255,0.05)' }}>
             <div className="flex gap-12 items-center">
                <div className="flex flex-col gap-1.5">
                  <span className="mono-label opacity-40 uppercase" style={{ color: contrastColor }}>swissflow.status</span>
                  <span className="text-[11px] font-black tracking-widest uppercase" style={{ color: contrastColor }}>continuous_flow</span>
                </div>
                <div className="w-px h-8 transition-colors" style={{ backgroundColor: contrastColor === '#FFFFFF' ? 'rgba(255,255,255,0.2)' : 'rgba(0,0,0,0.2)' }} />
                <div className="flex flex-col gap-1.5">
                  <span className="mono-label opacity-40 uppercase" style={{ color: contrastColor }}>proc.mode</span>
                  <span className="text-[11px] font-black tracking-widest uppercase" style={{ color: contrastColor }}>single_take</span>
                </div>
             </div>
             <div className="flex items-center gap-6">
                <span className="material-symbols-outlined text-[20px] opacity-10" style={{ color: contrastColor }}>motion_photos_on</span>
                <span className="material-symbols-outlined text-[20px] opacity-10" style={{ color: contrastColor }}>all_inclusive</span>
             </div>
          </footer>
        </main>
      </div>

      {/* Background Depth Elements */}
      <div className="fixed inset-0 pointer-events-none z-0">
         <div className="absolute top-1/2 left-1/2 -translate-x-1/2 -translate-y-1/2 flex items-center justify-center">
            <div className="w-20 h-[1px] transition-colors" style={{ backgroundColor: contrastColor === '#FFFFFF' ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)' }} />
            <div className="h-20 w-[1px] absolute transition-colors" style={{ backgroundColor: contrastColor === '#FFFFFF' ? 'rgba(255,255,255,0.1)' : 'rgba(0,0,0,0.1)' }} />
         </div>
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { SUPPORTED_LANGUAGES } from '../constants/Languages';
import { LanguageCode } from '../types';
import { TRANSLATIONS } from '../translations';

interface Props {
  onSelect: (code: LanguageCode) => void;
}

export const LanguageGate: React.FC<Props> = ({ onSelect }) => {
  const [selected, setSelected] = useState<LanguageCode>('en');
  const t = TRANSLATIONS[selected] || TRANSLATIONS['en'];

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#1a1a1a] swiss-grid p-6">
      <div className="w-full max-w-6xl bg-[#2a2a2a] border border-white flex flex-col relative overflow-hidden shadow-[0_0_150px_rgba(0,0,0,0.8)]">

        {/* Decorative Corner Markers */}
        <div className="absolute top-4 left-4 text-red-600 font-mono text-[10px] opacity-40 select-none">+</div>
        <div className="absolute top-4 right-4 text-red-600 font-mono text-[10px] opacity-40 select-none">+</div>
        <div className="absolute bottom-4 left-4 text-red-600 font-mono text-[10px] opacity-40 select-none z-50">+</div>
        <div className="absolute bottom-4 right-4 text-red-600 font-mono text-[10px] opacity-40 select-none z-50">+</div>

        {/* Top Section: Branding & Onboarding (Horizontal Layout) */}
        <div className="flex-1 p-12 lg:p-20 flex flex-col lg:flex-row gap-16 lg:gap-32 bg-black/20">

          {/* Left: Branding */}
          <div className="flex-1 flex flex-col justify-between min-w-0">
            <div className="flex flex-col gap-12">
              <div className="flex items-center gap-3">
                <div className="w-2.5 h-2.5 bg-red-600 rounded-full animate-pulse shadow-[0_0_15px_rgba(220,38,38,0.5)]" />
                <span className="mono-label font-bold text-white tracking-[0.5em]">swissflow.terminal</span>
              </div>

              <div className="flex flex-col gap-6">
                <h1 className="text-7xl xl:text-8xl font-black lowercase tracking-tighter italic leading-[0.75] text-white">
                  {t.welcomeTitle}
                </h1>
                <p className="text-white/60 text-[12px] lowercase font-medium tracking-[0.2em] leading-relaxed mt-4 max-w-sm">
                  {t.welcomeDesc}
                </p>
              </div>
            </div>

            <div className="hidden lg:flex flex-col gap-2 opacity-20 mt-12">
               <span className="mono-label text-[9px]">build_0.9.14_stable</span>
               <span className="mono-label text-[9px]">node.status // online</span>
            </div>
          </div>

          {/* Right: Prominent Onboarding */}
          <div className="flex-1">
             <div className="flex flex-col gap-10">
                <div className="flex items-center gap-6">
                   <div className="w-12 h-[1px] bg-red-600" />
                   <span className="mono-label text-red-600 font-black text-[10px] tracking-[0.4em]">{t.onboardingTitle}</span>
                </div>

                <div className="grid grid-cols-1 gap-6">
                   {[t.onboardingStep1, t.onboardingStep2, t.onboardingStep3].map((step, i) => {
                     const parts = step.split('. ');
                     const stepNum = parts[0];
                     const stepText = parts[1];

                     return (
                       <div key={i} className="flex gap-8 group cursor-default">
                         <div className="flex flex-col items-center">
                            <span className="text-3xl font-black italic tracking-tighter text-red-600 leading-none group-hover:scale-110 transition-transform duration-300">
                              0{stepNum}
                            </span>
                            <div className="w-px flex-1 bg-white/10 mt-4 group-last:hidden" />
                         </div>
                         <div className="flex flex-col gap-2 pt-1">
                            <span className="text-lg font-black italic tracking-tight text-white leading-tight lowercase">
                              {stepText}
                            </span>
                            <div className="h-px w-0 group-hover:w-full bg-red-600/30 transition-all duration-700" />
                         </div>
                       </div>
                     );
                   })}
                </div>
             </div>
          </div>
        </div>

        {/* Bottom Bar: Language & Action (Inline Horizontal Action Bar) */}
        <div className="flex flex-col md:flex-row border-t border-white bg-black/40 relative z-10 shrink-0">

          {/* Language Selection - Half Width Inline */}
          <div className="flex-1 p-12 lg:p-16 border-b md:border-b-0 border-white flex flex-col justify-center gap-6 relative group">
            <div className="flex flex-col gap-2">
              <span className="mono-label text-red-600 font-bold tracking-[0.3em]">{t.languageSelectTitle}</span>
              <p className="text-white/40 text-[10px] lowercase font-medium tracking-widest leading-tight">
                {t.languageSelectSub}
              </p>
            </div>

            <div className="relative border-b-2 border-white pb-2 group/select">
              <select
                value={selected}
                onChange={(e) => setSelected(e.target.value)}
                className="w-full h-16 bg-transparent border-none px-0 text-3xl font-black lowercase tracking-tighter italic appearance-none outline-none cursor-pointer text-white focus:text-red-600 transition-colors"
              >
                {SUPPORTED_LANGUAGES.map((lang) => (
                  <option key={lang.code} value={lang.code} className="bg-[#2a2a2a] text-white">
                    {lang.nativeLabel}
                  </option>
                ))}
              </select>
              <span className="material-symbols-outlined absolute right-0 top-1/2 -translate-y-1/2 text-red-600 pointer-events-none group-hover/select:translate-x-2 transition-transform text-2xl">
                expand_more
              </span>
            </div>
          </div>

          {/* Action Button - Unified background with black/40 */}
          <div className="flex-1 flex p-8 lg:p-10 bg-black/40">
            <button
              onClick={() => onSelect(selected)}
              className="w-full h-full bg-red-600 text-white font-black text-[14px] uppercase tracking-[0.6em] flex items-center justify-center gap-6 transition-all relative overflow-hidden group shadow-[0_20px_50px_rgba(220,38,38,0.3)] border-2 border-transparent hover:border-white hover:scale-[1.02] active:scale-[0.98]"
            >
              <div className="absolute inset-0 bg-white translate-y-full group-hover:translate-y-0 transition-transform duration-300 ease-[var(--expo-ease)]" />
              <span className="relative z-10 flex items-center gap-4 group-hover:text-black transition-colors duration-300">
                {t.languageSelectAction}
                <span className="material-symbols-outlined text-[28px] group-hover:translate-x-2 transition-transform duration-500">
                  arrow_right_alt
                </span>
              </span>

              {/* Tactical Button Accents */}
              <div className="absolute top-0 right-0 p-2 opacity-20 group-hover:opacity-100 transition-opacity">
                <div className="w-1.5 h-1.5 border-t border-r border-white" />
              </div>
              <div className="absolute bottom-0 left-0 p-2 opacity-20 group-hover:opacity-100 transition-opacity">
                <div className="w-1.5 h-1.5 border-b border-l border-white" />
              </div>
            </button>
          </div>
        </div>

        {/* Backdrop Watermark */}
        <div className="absolute bottom-4 left-1/2 -translate-x-1/2 text-[10vw] font-black italic text-white/[0.01] pointer-events-none select-none leading-none z-0">
          COLLAGE_ENGINE
        </div>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { SUPPORTED_LANGUAGES } from '../constants/Languages';
import { GeneratedVideo, LanguageCode, TranslationStrings, StyleSettings, ReferenceAsset } from '../types';
import { ReferenceManager } from './ReferenceManager';

interface Props {
  onVideoGen: (video: GeneratedVideo) => void;
  langCode: LanguageCode;
  t: TranslationStrings;
  resolution: '360p' | '720p';
  setResolution: (res: '360p' | '720p') => void;
  aspectRatio: '16:9' | '9:16';
  setAspectRatio: (ratio: '16:9' | '9:16') => void;
  styleSettings: StyleSettings;
  contrastColor: string;
  setGlobalLoading: (loading: boolean) => void;
  setGlobalError: (error: string | null) => void;
}

const ControlLabel: React.FC<{ children: React.ReactNode; technical?: string; contrastColor: string }> = ({ children, technical, contrastColor }) => (
  <div className="flex justify-between items-center mb-4">
    <label className="text-[11px] font-black uppercase tracking-[0.25em] block lowercase" style={{ color: contrastColor }}>
      {children}
    </label>
    {technical && <span className="text-[9px] font-mono opacity-40 uppercase tracking-tighter" style={{ color: contrastColor }}>[{technical}]</span>}
  </div>
);

const TechButton: React.FC<{ 
  active: boolean; 
  locked?: boolean;
  onClick: () => void; 
  children: React.ReactNode;
  activeColor?: string;
  contrastColor: string;
}> = ({ active, locked, onClick, children, activeColor = '#FF0000', contrastColor }) => (
  <button
    onClick={onClick}
    className={`flex-1 h-14 flex items-center justify-center transition-all border-r last:border-r-0 ${
      active 
        ? 'font-black' 
        : locked ? 'opacity-20 bg-black/20' : 'bg-transparent hover:bg-white/[0.1]'
    } text-[10px] uppercase tracking-[0.35em] relative group cursor-default`}
    style={{ 
      borderColor: contrastColor,
      backgroundColor: active ? activeColor : 'transparent',
      color: active ? (activeColor === '#FFFFFF' ? '#000000' : '#FFFFFF') : contrastColor,
    }}
  >
    {active && <div className="absolute top-0 left-0 w-full h-[2px] bg-white/40" />}
    <span className={active ? '' : 'opacity-40'}>{children}</span>
  </button>
);

export const Step1VideoGen: React.FC<Props> = ({ 
  onVideoGen, 
  langCode, 
  t,
  resolution,
  setResolution,
  aspectRatio,
  setAspectRatio,
  styleSettings,
  contrastColor,
  setGlobalLoading,
  setGlobalError
}) => {
  const [sceneDesc, setSceneDesc] = useState('');
  const [script, setScript] = useState('');
  const [autoGenScript, setAutoGenScript] = useState(false);

  const [duration, setDuration] = useState(8);
  const [narration, setNarration] = useState<'female' | 'male' | 'none'>('none');
  const [useMusic, setUseMusic] = useState(true);
  const [showText, setShowText] = useState(true);
  const [loading, setLoading] = useState(false);

  const [useReferences, setUseReferences] = useState(false);
  const [assets, setAssets] = useState<ReferenceAsset[]>([]);

  const canUseVoice = autoGenScript || script.trim().length > 0;

  useEffect(() => {
    if (!canUseVoice && narration !== 'none') {
      setNarration('none');
    }
  }, [canUseVoice, narration]);

  const handleVoiceClick = (voice: 'female' | 'male') => {
    if (!canUseVoice) {
      setGlobalError("SYSTEM_LOCK: REQUIRE_NARRATION_SCRIPT_INPUT_TO_ACTIVATE_VOICE");
      return;
    }
    setNarration(voice);
  };

  const handleGenerate = async () => {
    if (!sceneDesc.trim()) {
      setGlobalError("[!] ERROR: SCENE DESCRIPTION REQUIRED");
      return;
    }

    setGlobalError(null);
    setLoading(true);
    setGlobalLoading(true);

    try {
      const langLabel = SUPPORTED_LANGUAGES.find(l => l.code === langCode)?.label || 'English';

      let finalScript = script;
      if (autoGenScript) {
        const { text } = await Flow.generate.text(
          `Generate a very short, poetic, 1-2 sentence narration script for a video based on this description: "${sceneDesc}". The script should be in ${langLabel}. Output only the script text.`,
          { systemInstruction: 'You are a minimalist script writer for artistic editorial videos.' }
        );
        finalScript = text;
      }

      let collageInstructions = '';
      const referenceMediaIds: string[] = [];

      if (useReferences) {
        const validAssets = assets.filter(a => a.status === 'ready' && a.name.trim());
        for (const asset of validAssets) {
          const regex = new RegExp(`\\b${asset.name}\\b`, 'i');
          if (regex.test(sceneDesc) || regex.test(finalScript)) {
            if (!asset.mediaId) {
              const { mediaId } = await Flow.upload({
                base64: asset.processedBase64,
                mimeType: 'image/png',
                name: `REF_${asset.name}`
              });
              asset.mediaId = mediaId;
            }
            if (asset.mediaId) {
              referenceMediaIds.push(asset.mediaId);
              collageInstructions += `
                SUBJECT OVERRIDE FOR '${asset.name}': Use reference as razor-sharp photographic cutout. POSITION: Center.
              `;
            }
          }
        }
      }

      const treatmentMap = {
        'grayscale': 'High-contrast desaturated grayscale treatment.',
        'duotone': `Extreme duotone using ${styleSettings.accentColor} mapping.`,
        'full-color': 'High-saturation color.'
      };

      const fullPrompt = `
        SCENE DESCRIPTION: "${sceneDesc}"
        ${finalScript ? `NARRATION SCRIPT: "${finalScript}"` : ''}
        AESTHETIC: Swiss Modernist Architectural Blueprint Collage.

        LAYERED DEPTH:
        1. Background: Flat color ${styleSettings.backgroundColor} (Infinite Canvas).
        2. Midground: Solid ${styleSettings.accentColor} primitive shapes behind subjects.
        3. Foreground: Isolated subject cutouts from description as RAZOR-SHARP extractions. ${treatmentMap[styleSettings.imageryTreatment]} ZERO strokes/borders.
        ${showText && finalScript ? `4. Text Strategy: LITERARY SUBTITLES. Generate kinetic typography that STRICTLY FOLLOWS THE NARRATION SCRIPT WORD-FOR-WORD. Do not truncate. (Color: ${styleSettings.typographyColor}, Language: ${langLabel}).` : ''}

        AUDIO SYNC:
        ${narration !== 'none' && finalScript ? `Voice narration must read the script word-for-word: "${finalScript}".` : ''}

        CONTINUOUS SINGLE-TAKE MOTION SYSTEM (STRICT):
        - PHILOSOPHY: One unbroken journey. No hard cuts.
        - START & END: 100% blank canvas of ${styleSettings.backgroundColor} for a perfect loop.
        - THE BUILD: Sequential assembly. UI/Grid fades in. Geometric accents slide in from behind camera. Subjects snap in. Subtitles cascade in.
        - NO CUTS: Transitions must be fluid.
        - THE TEARDOWN: In final 1s, reverse assembly.
        - PHYSICS: Extreme Bezier easing (cubic-bezier(0.87, 0, 0.13, 1)).
        - CONSTANT DRIFT: Slow persistent Z-axis zoom (+2%) during all segments.

        ${collageInstructions}

        --no cuts, whip pans, white border, sticker effect, paper cutout, stroke, glow, feathering, random text, gibberish, nonsensical characters, placeholder text, barcodes, qr codes, metadata text${!showText ? ', text, typography' : ''}
      `;

      const result = await Flow.generate.video({
        prompt: fullPrompt,
        aspectRatio: aspectRatio,
        modelDisplayName: 'Omni 1.1 Flash',
        durationSeconds: duration,
        resolution: resolution,
        referenceImageMediaIds: referenceMediaIds.length > 0 ? referenceMediaIds : undefined
      });

      onVideoGen({
        mediaId: result.mediaId,
        base64: result.base64,
        mimeType: result.mimeType,
        duration: duration
      });
    } catch (err) {
      console.error(err);
      setGlobalError(t.errorGen);
    } finally {
      setLoading(false);
      setGlobalLoading(false);
    }
  };

  return (
    <div className="w-full flex flex-col xl:flex-row border-b bg-black/5" style={{ borderColor: contrastColor }}>

      {/* Editorial Input Area */}
      <div className="flex-1 p-12 lg:p-16 border-r flex flex-col gap-16 transition-colors" style={{ borderColor: contrastColor }}>

        {/* Scene Description Box */}
        <div className="flex flex-col gap-6">
          <ControlLabel technical="scene.descriptor" contrastColor={contrastColor}>{t.sceneLabel}</ControlLabel>
          <div className="relative group">
             <div className="absolute -top-2 -left-2 w-4 h-4 border-t-2 border-l-2" style={{ borderColor: styleSettings.accentColor }} />
             <div className="absolute -bottom-2 -right-2 w-4 h-4 border-b-2 border-r-2" style={{ borderColor: styleSettings.accentColor }} />
             <textarea
                value={sceneDesc}
                onChange={(e) => setSceneDesc(e.target.value)}
                placeholder={t.scenePlaceholder}
                className="w-full h-44 bg-white/[0.04] p-10 text-xl font-black italic tracking-tighter outline-none transition-all resize-none dark-scrollbar lowercase leading-tight border focus:bg-white/[0.08]"
                style={{ color: contrastColor, borderColor: contrastColor } as any}
              />
          </div>
        </div>

        {/* Script Box */}
        <div className="flex flex-col gap-6">
          <div className="flex justify-between items-center">
             <ControlLabel technical="narration.script" contrastColor={contrastColor}>{t.scriptLabel}</ControlLabel>
             <button 
               onClick={() => setAutoGenScript(!autoGenScript)}
               className="flex items-center gap-3 px-6 py-2 rounded-xl border transition-all relative overflow-hidden group shadow-lg"
               style={{ 
                 borderColor: contrastColor, 
                 backgroundColor: autoGenScript ? styleSettings.accentColor : 'transparent',
                 color: autoGenScript ? '#FFFFFF' : contrastColor
               }}
             >
                <span className="material-symbols-outlined text-[18px]">{autoGenScript ? 'auto_awesome' : 'edit_note'}</span>
                <span className="mono-label text-[10px] font-black">{t.scriptAutoLabel}</span>
                {autoGenScript && <div className="absolute inset-0 bg-white/10 animate-pulse" />}
             </button>
          </div>
          <div className={`relative group transition-opacity duration-500 ${autoGenScript ? 'opacity-20' : 'opacity-100'}`}>
             <div className="absolute -top-2 -left-2 w-4 h-4 border-t-2 border-l-2" style={{ borderColor: styleSettings.accentColor }} />
             <div className="absolute -bottom-2 -right-2 w-4 h-4 border-b-2 border-r-2" style={{ borderColor: styleSettings.accentColor }} />
             <textarea
                value={script}
                disabled={autoGenScript}
                onChange={(e) => setScript(e.target.value)}
                placeholder={autoGenScript ? "[script_auto_mode_active]" : t.scriptPlaceholder}
                className="w-full h-44 bg-white/[0.04] p-10 text-xl font-black italic tracking-tighter outline-none transition-all resize-none dark-scrollbar lowercase leading-tight border focus:bg-white/[0.08]"
                style={{ color: contrastColor, borderColor: contrastColor } as any}
              />
          </div>
        </div>

        {/* References */}
        <div className="flex flex-col gap-10 bg-white/[0.05] p-10 rounded-3xl border shadow-xl transition-colors" style={{ borderColor: contrastColor }}>
           <div className="flex items-center justify-between">
              <div className="flex items-center gap-4">
                 <div className="w-2 h-2 rounded-sm rotate-45" style={{ backgroundColor: styleSettings.accentColor }} />
                 <span className="mono-label font-bold uppercase tracking-widest" style={{ color: contrastColor }}>{t.refToggleLabel}</span>
              </div>
              <button 
                onClick={() => setUseReferences(!useReferences)}
                className="w-14 h-7 rounded-full transition-all relative border"
                style={{ borderColor: contrastColor, backgroundColor: useReferences ? styleSettings.accentColor : 'transparent' }}
              >
                <div className={`absolute top-0.5 w-5 h-5 rounded-full bg-white transition-all shadow-lg ${useReferences ? 'left-[30px]' : 'left-0.5'}`} />
              </button>
           </div>

           {useReferences && (
             <ReferenceManager 
               assets={assets} 
               setAssets={setAssets} 
               styleSettings={styleSettings} 
               t={t} 
               contrastColor={contrastColor}
             />
           )}
        </div>
      </div>

      {/* Rendering Sidebar */}
      <div className="w-full xl:w-[400px] flex flex-col bg-black/20 border-l transition-colors" style={{ borderColor: contrastColor }}>
        <div className="p-12 lg:p-16 flex-1 flex flex-col gap-10">

          {/* Narrator Voice */}
          <div className="flex flex-col gap-6">
              <ControlLabel technical="audio.narrator" contrastColor={contrastColor}>{t.voiceLabel}</ControlLabel>
              <div className="flex flex-col border border-white/10 bg-black/40 rounded-2xl overflow-hidden shadow-2xl transition-colors" style={{ borderColor: contrastColor }}>
                <div className="flex h-14">
                  <TechButton 
                    active={narration === 'female'} 
                    locked={!canUseVoice} 
                    onClick={() => handleVoiceClick('female')} 
                    activeColor={styleSettings.accentColor} 
                    contrastColor={contrastColor}
                  >
                    {t.voiceFemale}
                  </TechButton>
                  <TechButton 
                    active={narration === 'male'} 
                    locked={!canUseVoice} 
                    onClick={() => handleVoiceClick('male')} 
                    activeColor={styleSettings.accentColor} 
                    contrastColor={contrastColor}
                  >
                    {t.voiceMale}
                  </TechButton>
                  <TechButton 
                    active={narration === 'none'} 
                    onClick={() => setNarration('none')} 
                    activeColor={styleSettings.accentColor} 
                    contrastColor={contrastColor}
                  >
                    {t.voiceNone}
                  </TechButton>
                </div>
              </div>
              {!canUseVoice && <span className="mono-label text-[8px] opacity-30 text-center lowercase" style={{ color: contrastColor }}>[narrator_locked: require_script]</span>}
           </div>

          {/* Subtitles */}
          <div className="flex flex-col gap-6">
            <ControlLabel technical="visual.text" contrastColor={contrastColor}>{t.textToggleLabel}</ControlLabel>
            <div className="flex border bg-black/40 rounded-2xl overflow-hidden shadow-lg transition-colors" style={{ borderColor: contrastColor }}>
               <TechButton active={showText} onClick={() => setShowText(true)} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>{t.textOn}</TechButton>
               <TechButton active={!showText} onClick={() => setShowText(false)} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>{t.textOff}</TechButton>
            </div>
          </div>

          {/* Background Score */}
          <div className="flex flex-col gap-6">
              <ControlLabel technical="audio.score" contrastColor={contrastColor}>{t.musicLabel}</ControlLabel>
              <div className="flex flex-col border border-white/10 bg-black/40 rounded-2xl overflow-hidden shadow-2xl transition-colors" style={{ borderColor: contrastColor }}>
                <div className="flex h-14">
                  <TechButton active={useMusic} onClick={() => setUseMusic(true)} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>{t.musicOn}</TechButton>
                  <TechButton active={!useMusic} onClick={() => setUseMusic(false)} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>{t.musicOff}</TechButton>
                </div>
              </div>
           </div>

          <div className="flex flex-col gap-8">
            <ControlLabel technical="timer.duration" contrastColor={contrastColor}>{t.durationLabel}</ControlLabel>
            <div className="flex flex-col gap-6 bg-white/[0.05] p-10 rounded-2xl border shadow-inner transition-colors" style={{ borderColor: contrastColor }}>
              <span className="text-7xl font-black italic tracking-tighter leading-none" style={{ color: styleSettings.accentColor }}>{duration}s</span>
              <div className="flex flex-col gap-px w-full pt-4">
                <input 
                  type="range" min={4} max={10} step={1} value={duration}
                  onChange={(e) => setDuration(Number(e.target.value))}
                  className="w-full appearance-none h-[3px] cursor-pointer"
                  style={{ accentColor: styleSettings.accentColor }}
                />
              </div>
            </div>
          </div>

          <div className="flex flex-col gap-6">
            <ControlLabel technical="raster.res" contrastColor={contrastColor}>{t.resLabel}</ControlLabel>
            <div className="flex border bg-black/40 rounded-2xl overflow-hidden shadow-lg transition-colors" style={{ borderColor: contrastColor }}>
              <TechButton active={resolution === '360p'} onClick={() => setResolution('360p')} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>360p {t.draftLabel}</TechButton>
              <TechButton active={resolution === '720p'} onClick={() => setResolution('720p')} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>720p {t.hdLabel}</TechButton>
            </div>
          </div>

          <div className="flex flex-col gap-6">
            <ControlLabel technical="aspect.bounds" contrastColor={contrastColor}>{t.aspectLabel}</ControlLabel>
            <div className="grid grid-cols-2 border bg-black/40 rounded-2xl overflow-hidden shadow-lg transition-colors" style={{ borderColor: contrastColor }}>
              <TechButton active={aspectRatio === '16:9'} onClick={() => setAspectRatio('16:9')} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>
                16:9 {t.landscapeLabel}
              </TechButton>
              <TechButton active={aspectRatio === '9:16'} onClick={() => setAspectRatio('9:16')} activeColor={styleSettings.accentColor} contrastColor={contrastColor}>
                9:16 {t.portraitLabel}
              </TechButton>
            </div>
          </div>
        </div>

        <button
          onClick={handleGenerate}
          disabled={loading}
          className="h-40 w-full bg-white text-black font-black uppercase tracking-[1em] text-[12px] hover:text-white transition-all relative overflow-hidden group shadow-[0_-20px_50px_rgba(0,0,0,0.3)]"
          style={{ '--hover-bg': styleSettings.accentColor } as any}
        >
          <div className="absolute inset-0 bg-transparent group-hover:bg-[var(--hover-bg)] transition-colors duration-700" />
          <div className="relative z-10 flex flex-col items-center gap-4">
            {loading ? (
              <div className="flex items-center gap-6">
                <div className="w-3 h-3 rounded-full bg-black animate-ping" />
                <span className="tracking-[0.5em]">{t.genLoading}</span>
              </div>
            ) : (
              <>
                <span className="material-symbols-outlined text-5xl group-hover:scale-110 transition-transform duration-500">videocam</span>
                <span>{t.genBtn}</span>
              </>
            )}
          </div>
        </button>
      </div>
    </div>
  );
};

import React, { useState, useEffect } from 'react';
import { Flow } from 'flow-sdk';
import { GeneratedVideo, TranslationStrings, StyleSettings } from '../types';

interface Props {
  video: GeneratedVideo | null;
  t: TranslationStrings;
  resolution: '360p' | '720p';
  aspectRatio: '16:9' | '9:16';
  styleSettings: StyleSettings;
  contrastColor: string;
}

export const Step2Preview: React.FC<Props> = ({ video, t, resolution, aspectRatio, styleSettings, contrastColor }) => {
  const [downloadState, setDownloadState] = useState<'idle' | 'downloading' | 'done'>('idle');
  const [blobUrl, setBlobUrl] = useState<string | null>(null);

  useEffect(() => {
    if (video) {
      const bytes = Uint8Array.from(atob(video.base64), c => c.charCodeAt(0));
      const blob = new Blob([bytes], { type: video.mimeType });
      const url = URL.createObjectURL(blob);
      setBlobUrl(url);
      return () => URL.revokeObjectURL(url);
    }
  }, [video]);

  const handleDownload = async () => {
    if (!video) return;
    setDownloadState('downloading');
    try {
      await Flow.download({
        base64: video.base64,
        mimeType: video.mimeType,
        filename: `editorial_MASTER_${Date.now()}.mp4`
      });
      setDownloadState('done');
      setTimeout(() => setDownloadState('idle'), 3000);
    } catch (err) {
      console.error(err);
      setDownloadState('idle');
    }
  };

  if (!video) return null;

  return (
    <section 
      id="preview-section"
      className="w-full flex flex-col xl:flex-row bg-black/10 animate-in fade-in slide-in-from-bottom-12 duration-1000"
