      <div className="flex-1 p-10 lg:p-20 border-r relative transition-colors" style={{ borderColor: contrastColor }}>
        {/* Frame Markers */}
        <div className="absolute top-12 left-12 text-lg opacity-60 z-10 font-black" style={{ color: contrastColor }}>┌</div>
        <div className="absolute top-12 right-12 text-lg opacity-60 z-10 font-black" style={{ color: contrastColor }}>┐</div>
        <div className="absolute bottom-12 left-12 text-lg opacity-60 z-10 font-black" style={{ color: contrastColor }}>└</div>
        <div className="absolute bottom-12 right-12 text-lg opacity-60 z-10 font-black" style={{ color: contrastColor }}>┘</div>

        <div className="relative flex flex-col items-center justify-center h-full">
          <div className="absolute top-0 left-1/2 -translate-x-1/2 flex items-center gap-12 px-6 py-2 border-x border-b bg-black/60 rounded-b-xl z-20 transition-colors" style={{ borderColor: contrastColor }}>
             <div className="flex items-center gap-2">
                <div className="w-1.5 h-1.5 rounded-full" style={{ backgroundColor: styleSettings.accentColor }} />
                <span className="mono-label uppercase" style={{ color: contrastColor }}>preview.master</span>
             </div>
             <span className="mono-label opacity-40 uppercase" style={{ color: contrastColor }}>00:00:00:0{video.duration}</span>
          </div>

          <div className="w-full max-w-4xl relative group">
            <div 
              className="absolute -inset-4 transition-all duration-700 opacity-20 group-hover:opacity-40" 
              style={{ background: `radial-gradient(circle, ${styleSettings.accentColor}33 0%, transparent 70%)` }} 
            />
            <div className="relative shadow-[0_40px_100px_rgba(0,0,0,0.6)] rounded-lg overflow-hidden bg-black border" style={{ borderColor: contrastColor }}>
              {blobUrl && (
                <video 
                  autoPlay loop muted controls
                  className="w-full h-auto block"
                  src={blobUrl}
                />
              )}
            </div>
          </div>
        </div>
      </div>

      {/* Control Sidebar */}
      <div className="w-full xl:w-96 flex flex-col bg-white/[0.03] backdrop-blur-md border-l xl:border-l-0 transition-colors" style={{ borderColor: contrastColor }}>
        <div className="p-10 lg:p-12 flex-1 flex flex-col justify-between">
           <div className="flex flex-col gap-10">
              <div className="flex flex-col gap-4">
                 <div className="flex items-center gap-3">
                    <div className="w-4 h-[1px]" style={{ backgroundColor: styleSettings.accentColor }} />
                    <span className="mono-label uppercase tracking-widest" style={{ color: styleSettings.accentColor }}>editorial.metadata</span>
                 </div>
                 <h2 className="text-4xl font-black lowercase tracking-tighter italic leading-none" style={{ color: contrastColor }}>{t.step2Title}</h2>
                 <p className="text-[11px] lowercase font-medium tracking-[0.2em] leading-relaxed opacity-60" style={{ color: contrastColor }}>
                   {t.step2Desc}
                 </p>
              </div>

              <div className="flex flex-col gap-4 bg-white/[0.05] border p-8 rounded-xl shadow-xl relative overflow-hidden transition-colors" style={{ borderColor: contrastColor }}>
                 <div className="absolute top-0 right-0 p-2 opacity-10">
                    <span className="material-symbols-outlined text-4xl" style={{ color: contrastColor }}>slow_motion_video</span>
                 </div>
                 {[
                   { label: 'format', value: resolution },
                   { label: 'aspect', value: aspectRatio },
                   { label: 'engine', value: 'OMNI_1.1_FLASH' },
                   { label: 'codec', value: 'H.264_MODERN' }
                 ].map(item => (
                   <div key={item.label} className="flex justify-between items-center text-[10px] mono-label border-b pb-2 last:border-0 last:pb-0 transition-colors" style={{ borderColor: `${contrastColor}1A` }}>
