              </div>
           </div>
        </div>
      </div>
    </section>
  );
};

import React, { useState, useRef, useEffect } from 'react';
import { StyleSettings, ImageryTreatment, TranslationStrings } from '../types';

interface Props {
  settings: StyleSettings;
  onChange: (settings: StyleSettings) => void;
  t: TranslationStrings;
  contrastColor: string;
}

const InfoTooltip: React.FC<{ text: string; align?: 'left' | 'right' | 'center' }> = ({ text, align = 'center' }) => {
  const alignClasses = {
    left: 'left-0 translate-x-0',
    right: 'right-0 translate-x-0',
    center: 'left-1/2 -translate-x-1/2'
  };

  const arrowClasses = {
    left: 'left-2',
    right: 'right-2',
