import { useState, useCallback } from 'react';
import { pipeline, env, RawImage } from '@huggingface/transformers';
import { StyleSettings } from '../types';

env.allowLocalModels = false;
env.useBrowserCache = false;

let segmenterPromise: Promise<any> | null = null;

async function getSegmenter() {
  if (!segmenterPromise) {
    segmenterPromise = pipeline('image-segmentation', 'Xenova/modnet', {
      device: 'webgpu',
    });
  }
  return segmenterPromise;
}

export function useImageProcessor() {
  const [isProcessing, setIsProcessing] = useState(false);

  const processImage = useCallback(async (base64: string, settings: StyleSettings): Promise<string> => {
    setIsProcessing(true);
    try {
      const segmenter = await getSegmenter();
      const dataUrl = `data:image/png;base64,${base64}`;
      const image = await RawImage.fromURL(dataUrl);
      const output = await segmenter(image);
      const mask = output[0].mask;

      const canvas = document.createElement('canvas');
      canvas.width = image.width;
      canvas.height = image.height;
      const ctx = canvas.getContext('2d', { willReadFrequently: true })!;

      ctx.drawImage(await image.toCanvas(), 0, 0);
      const imgData = ctx.getImageData(0, 0, canvas.width, canvas.height);
      const maskResized = await mask.resize(image.width, image.height);

      for (let i = 0; i < imgData.data.length / 4; i++) {
        // STRICT RAZOR-SHARP EXTRACTION:
        // Apply immediate binary threshold to the alpha channel.
        // If mask > 127, pixel is fully opaque (255).
        // If mask <= 127, pixel is fully transparent (0).
        // This removes all soft feathering, glows, or transparency artifacts.
        imgData.data[i * 4 + 3] = maskResized.data[i] > 127 ? 255 : 0;

        // Apply Imagery Treatment
        if (settings.imageryTreatment === 'grayscale') {
          const r = imgData.data[i * 4];
          const g = imgData.data[i * 4 + 1];
          const b = imgData.data[i * 4 + 2];
          const gray = 0.299 * r + 0.587 * g + 0.114 * b;
          imgData.data[i * 4] = gray;
          imgData.data[i * 4 + 1] = gray;
          imgData.data[i * 4 + 2] = gray;
        } else if (settings.imageryTreatment === 'duotone') {
          const r = imgData.data[i * 4];
          const g = imgData.data[i * 4 + 1];
          const b = imgData.data[i * 4 + 2];
          const gray = (0.299 * r + 0.587 * g + 0.114 * b) / 255;

          const accent = hexToRgb(settings.accentColor) || { r: 255, g: 0, b: 0 };
          imgData.data[i * 4] = gray * accent.r;
          imgData.data[i * 4 + 1] = gray * accent.g;
          imgData.data[i * 4 + 2] = gray * accent.b;
        }
      }

      ctx.putImageData(imgData, 0, 0);
      return canvas.toDataURL('image/png').split(',')[1];
    } finally {
      setIsProcessing(false);
    }
  }, []);

  return { processImage, isProcessing };
}

function hexToRgb(hex: string) {
  const result = /^#?([a-f\d]{2})([a-f\d]{2})([a-f\d]{2})$/i.exec(hex);
  return result ? {
    r: parseInt(result[1], 16),
    g: parseInt(result[2], 16),
    b: parseInt(result[3], 16)
  } : null;
}

import React, { useRef } from 'react';
import { ReferenceAsset, StyleSettings, TranslationStrings } from '../types';
import { useImageProcessor } from '../hooks/useImageProcessor';

interface Props {
  assets: ReferenceAsset[];
  setAssets: React.Dispatch<React.SetStateAction<ReferenceAsset[]>>;
  styleSettings: StyleSettings;
  t: TranslationStrings;
  contrastColor: string;
}

export const ReferenceManager: React.FC<Props> = ({ assets, setAssets, styleSettings, t, contrastColor }) => {
  const fileInputRef = useRef<HTMLInputElement>(null);
  const { processImage } = useImageProcessor();

  const handleFileChange = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(e.target.files || []);
    const remainingSlots = 4 - assets.length;
    const filesToProcess = files.slice(0, remainingSlots);

    for (const file of filesToProcess) {
      const reader = new FileReader();
      reader.onload = async () => {
        const base64 = (reader.result as string).split(',')[1];
        const newAsset: ReferenceAsset = {
          id: Math.random().toString(36).substr(2, 9),
          name: '',
          originalBase64: base64,
          processedBase64: '',
          status: 'processing'
        };

        setAssets(prev => [...prev, newAsset]);

        try {
          const processed = await processImage(base64, styleSettings);
          setAssets(prev => prev.map(a => 
            a.id === newAsset.id 
              ? { ...a, processedBase64: processed, status: 'ready' } 
              : a
          ));
        } catch (err) {
          console.error(err);
          setAssets(prev => prev.map(a => 
            a.id === newAsset.id ? { ...a, status: 'error' } : a
          ));
        }
      };
      reader.readAsDataURL(file);
    }
  };

  const updateAssetName = (id: string, name: string) => {
    setAssets(prev => prev.map(a => a.id === id ? { ...a, name } : a));
  };

  const removeAsset = (id: string) => {
    setAssets(prev => prev.filter(a => a.id !== id));
  };

  return (
    <div className="flex flex-col gap-6 animate-in fade-in slide-in-from-top-4 duration-500">
      <div className="flex justify-between items-center px-4 py-2 border-b transition-colors" style={{ borderColor: contrastColor }}>
        <span className="mono-label uppercase font-bold" style={{ color: styleSettings.accentColor }}>{t.refManagerTitle}</span>
        <span className="mono-label opacity-40 uppercase" style={{ color: contrastColor }}>{assets.length} / 4</span>
      </div>

      <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
        {assets.map((asset) => (
          <div key={asset.id} className="bg-white/[0.05] border rounded-xl p-4 flex flex-col gap-4 relative group shadow-lg transition-colors" style={{ borderColor: contrastColor }}>
            <button 
              onClick={() => removeAsset(asset.id)}
              className="absolute top-2 right-2 w-6 h-6 flex items-center justify-center transition-colors"
              style={{ color: `${contrastColor}4D` }}
            >
              <span className="material-symbols-outlined text-sm hover:text-red-600">close</span>
            </button>

            <div className="aspect-square w-full bg-black/40 rounded-lg overflow-hidden flex items-center justify-center relative border transition-colors" style={{ borderColor: `${contrastColor}33` }}>
              {asset.status === 'processing' ? (
                <div className="flex flex-col items-center gap-2">
                  <div className="w-4 h-4 border-2 border-red-600 border-t-transparent rounded-full animate-spin" />
                  <span className="mono-label text-[8px] uppercase" style={{ color: contrastColor }}>{t.refProcessing}</span>
                </div>
              ) : asset.processedBase64 ? (
                <img src={`data:image/png;base64,${asset.processedBase64}`} className="max-w-[80%] max-h-[80%] object-contain" />
              ) : (
                <span className="material-symbols-outlined opacity-10 text-4xl" style={{ color: contrastColor }}>image_not_supported</span>
              )}
              {/* Reference Grid Overlay */}
              <div className="absolute inset-0 pointer-events-none opacity-20">
                <div className="absolute top-1/2 left-0 w-full h-[1px]" style={{ backgroundColor: contrastColor }} />
                <div className="absolute top-0 left-1/2 w-[1px] h-full" style={{ backgroundColor: contrastColor }} />
              </div>
            </div>

            <div className="flex flex-col gap-2">
              <input 
                type="text"
                value={asset.name}
                onChange={(e) => updateAssetName(asset.id, e.target.value)}
                placeholder={t.refNamePlaceholder}
                className="w-full bg-transparent border-b py-1 text-[11px] font-bold tracking-tighter outline-none focus:border-red-600 transition-colors"
                style={{ color: contrastColor, borderColor: `${contrastColor}33` }}
              />
            </div>
          </div>
        ))}

        {assets.length < 4 && (
          <button 
            onClick={() => fileInputRef.current?.click()}
            className="aspect-square w-full border-2 border-dashed hover:bg-white/[0.1] rounded-xl flex flex-col items-center justify-center gap-4 transition-all group"
            style={{ borderColor: `${contrastColor}4D` }}
          >
            <span className="material-symbols-outlined text-4xl transition-colors" style={{ color: `${contrastColor}33` }}>add_photo_alternate</span>
            <span className="mono-label opacity-40 text-[9px] uppercase" style={{ color: contrastColor }}>{t.refUploadHint}</span>
          </button>
        )}
      </div>
      <input 
        ref={fileInputRef} 
        type="file" 
        multiple 
        accept="image/*" 
        className="hidden" 
        onChange={handleFileChange} 
      />
    </div>
  );
};
